function morphshape23(ctx,ctrans,frame,ratio,time){
	var pathData="M -3699 -3699 -207 -207 L -3699 -3699 241 241 -3619 -2019 241 241 -3619 -2019 -207 -207 -3699 -3699 -207 -207";
	ctx.fillStyle=tocolor(ctrans.apply([Math.round(0+ratio*(0)/65535),Math.round(0+ratio*(0)/65535),Math.round(204+ratio*(1)/65535),((Math.round(51+ratio*(0)/65535))/255)]));
	drawMorphPath(ctx,pathData,ratio,false);

	ctx.fill("evenodd");
	var pathData="M -3699 -3699 -207 -207 L -3619 -2019 -207 -207 -3619 -2019 241 241 -3699 -3699 241 241 -3699 -3699 -207 -207 Z";
	var scaleMode = "NORMAL";
	ctx.strokeStyle=tocolor(ctrans.apply([Math.round(0+ratio*(0)/65535),Math.round(0+ratio*(0)/65535),Math.round(0+ratio*(1)/65535),((Math.round(0+ratio*(0)/65535))/255)]));
	ctx.lineWidth=0.0+ratio*(0)/65535;
	ctx.lineCap="round";
	ctx.lineJoin="round";
	drawMorphPath(ctx,pathData,ratio,true,scaleMode);

}

